/**
 * REVEAL OR HIDE A TERMINAL PAGE
 *
 * PAGE_UUID must identify a Terminal page imported into the world.
 * MODE accepts three values:
 *   "show"   : make the page visible;
 *   "hide"   : hide the page;
 *   "toggle" : reverse its current state.
 *
 * A hidden page disappears from automatic player menus. Its content is not
 * deleted and can be revealed again with the same macro.
 */

// ── CONFIGURATION TO EDIT ─────────────────────────────────────
const PAGE_UUID = "JournalEntry.REPLACE_ME.JournalEntryPage.REPLACE_ME";
const MODE = "toggle"; // "show", "hide", or "toggle"
// ──────────────────────────────────────────────────────────────

if (!game.user.isGM) return ui.notifications.error("This macro is for the GM only.");
if (!game.modules.get("retro-crt-terminal")?.active) {
  return ui.notifications.error("Retro CRT Terminal is not active.");
}
if (!PAGE_UUID || PAGE_UUID.includes("REPLACE_ME")) {
  return ui.notifications.warn("Edit PAGE_UUID in the macro configuration.");
}
if (!["show", "hide", "toggle"].includes(MODE)) {
  return ui.notifications.error("MODE must be show, hide, or toggle.");
}

const page = await foundry.utils.fromUuid(PAGE_UUID);
if (page?.documentName !== "JournalEntryPage" || page.type !== "retro-crt-terminal.terminal") {
  return ui.notifications.error("PAGE_UUID does not identify a Retro CRT Terminal page.");
}

const current = page.system.release.visibility;
const visibility = MODE === "show" ? "visible" : MODE === "hide" ? "hidden" : current === "hidden" ? "visible" : "hidden";
await page.update({ "system.release.visibility": visibility });
ui.notifications.info(`${page.name} is now ${visibility}.`);
